text:
Class component required — hooks can't catch render errors.

```tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

// ── Types ──────────────────────────────────────────────────────────────────
interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

// ── Logger ─────────────────────────────────────────────────────────────────
function logError(error: Error, info: ErrorInfo) {
  console.group("[ErrorBoundary]");
  console.error("Error:", error.message);
  console.error("Stack:", error.stack);
  console.error("Component trace:", info.componentStack);
  console.groupEnd();

  // Swap in real service: Sentry.captureException(error, { extra: info })
}

// ── Component ──────────────────────────────────────────────────────────────
export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    logError(error, info);
    this.props.onError?.(error, info);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    // Custom fallback wins
    if (fallback) return fallback(error, this.reset);

    // Default fallback UI
    return <DefaultFallback error={error} reset={this.reset} />;
  }
}

// ── Default Fallback ───────────────────────────────────────────────────────
function DefaultFallback({ error, reset }: { error: Error; reset: () => void }) {
  return (
    <div role="alert" style={styles.container}>
      <span style={styles.icon}>⚠️</span>
      <h2 style={styles.title}>Something went wrong</h2>
      <pre style={styles.message}>{error.message}</pre>
      <button onClick={reset} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

const styles = {
  container: {
    display: "flex",
    flexDirection: "column" as const,
    alignItems: "center",
    gap: "12px",
    padding: "32px",
    border: "1px solid #f87171",
    borderRadius: "8px",
    background: "#fef2f2",
    fontFamily: "sans-serif",
  },
  icon:    { fontSize: "2rem" },
  title:   { margin: 0, color: "#991b1b" },
  message: {
    margin: 0,
    padding: "8px 12px",
    background: "#fee2e2",
    borderRadius: "4px",
    fontSize: "0.85rem",
    color: "#7f1d1d",
    maxWidth: "100%",
    overflowX: "auto" as const,
  },
  button: {
    padding: "8px 20px",
    background: "#dc2626",
    color: "#fff",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
    fontWeight: 600,
  },
};
```

**Usage — three patterns:**

```tsx
// 1. Default fallback
<ErrorBoundary>
  <MyWidget />
</ErrorBoundary>

// 2. Custom fallback render prop
<ErrorBoundary fallback={(err, reset) => (
  <div>
    <p>Broke: {err.message}</p>
    <button onClick={reset}>Retry</button>
  </div>
)}>
  <MyWidget />
</ErrorBoundary>

// 3. Hook into error reporting
<ErrorBoundary onError={(err, info) => sentryCapture(err, info)}>
  <MyWidget />
</ErrorBoundary>
```

---

**Key decisions:**

| Choice | Why |
|--------|-----|
| `getDerivedStateFromError` | Set state before repaint — no flicker |
| `componentDidCatch` | Side-effects (log/report) go here, not above |
| `reset` resets state only | Child re-mounts fresh; parent state untouched |
| `role="alert"` | Screen readers announce error immediately |
| Render prop `fallback` | Caller controls UI without subclassing |

**Retry limit** if crash-loop risk:

```tsx
state = { error: null, retries: 0 };

reset = () => {
  if (this.state.retries >= 3) return;
  this.setState(s => ({ error: null, retries: s.retries + 1 }));
};
```
